findings.original:
def admit(req):
  if inflight >= limit:
    if req.priority < CRITICAL:
      return reject(503, retry_after=1)
  if req.enqueued_at + req.timeout < now():
    return drop()   # client gone
  return process(req)

findings.correction:
def admit(req):
  if req.deadline <= now():
    return reject(503)
  # Priority is assigned by trusted policy.
  # Lower classes have smaller limits.
  cap = limits[req.trusted_priority]
  if not slots.try_acquire_below(cap):
    return reject(503, retry_after=1)
  try:
    return process(req)
  finally:
    slots.release()
